    verseNumber: 42,
    speaker: "सञ्जय उवाच",
    sanskrit: "यामिमां पुष्पितां वाचं प्रवदन्त्यविप���्चितः।\nवेदवादरताः पार्थ नान्यदस्तीति वादिनः॥",
    transliteration: "yāmimāṁ puṣhpitāṁ vāchaṁ pravadanty-avipaśhchitaḥ\nveda-vāda-ratāḥ pārtha nānyad astīti vādinaḥ\nkāmātmānaḥ swarga-parā janma-karma-phala-pradām\nkriyā-viśheṣha-bahulāṁ bhogaiśhwarya-gatiṁ prati",
