    transliteration: "Śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt |\nSvadharme nidhanaṁ śreyaḥ paradharmo bhayāvahaः ||",
    hindi: "अच्छी प्रकार अनुष्ठान किए हुए दूसरे के धर्म से अपना गुणरहित स्वधर्म ही श्रेष्ठ है। स्वधर्म में मरना भी कल्याणकारी है और दूसरे का धर्म भय देने वाला है।",
