    transliteration: "yuktaḥ karma-phalaṁ tyaktvā śhāntim āpnoti naiṣhṭhikīm\nayuktaḥ kāma-kāreṇa phale sakto nibadhyate",
    hindi: "युक्त पुरुष कर्मफल का त्याग करके परम शान्ति को प्राप्त होता है; और अयुक्त पुरुष फल में आसक्त हुआ कामना के द्वारा बँधता है।।",
    english: "The one who is united (the well-poised or harmonized) having abandoned the fruit of action attains eternal peace; whereas the one who is not united (the unsteady or unbalanced), impelled by desire and attached to the fruit, is bound.",
