    bookId: "bhagavad-gita",
    verseNumber: 12,
    speaker: "श्रीभगवानुवाच",
    sanskrit: "सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च।\nमूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम्॥",
    transliteration: "sarva-dvārāṇi sanyamya mano hṛidi nirudhya cha\nmūrdhnyādhāyātmanaḥ prāṇam āsthito yoga-dhāraṇām",
    hindi: "सब (इन्द्रियों के) द्वारों को संयमित कर मन को हृदय में स्थिर करके और प्राण को मस्तक में स्थापित करके योगधारणा में स्थित हुआ।।",
    english: "Having closed all the gates, confined the mind in the heart, and fixed the life-breath in the head, engage in the practice of concentration.",
