    verseNumber: 20,
    speaker: "श्रीभगवानुवाच",
    sanskrit: "अहमात्मा गुडाकेश सर्वभूताशयस्थितः ।\nअहमादिश्च मध्यं च भूतानामन्त एव च ॥",
    transliteration: "Ahamātmā guḍākeśa sarvabhūtāśayasthitaḥ |\nAhamādiśca madhyaṁ ca bhūtānāmanta eva ca ||",
