    hindi: "हे महाबाहो! प्रकृति से उत्पन्न सात्त्विक, राजसिक और तामसिक—ये तीनों गुण अविनाशी जीवात्मा को शरीर में बाँधते हैं।",
    english: "Sattva (purity), Rajas (passion), and Tamas (ignorance)—these three modes born of material nature bind the imperishable soul within the body, O mighty-armed Arjuna.",
