    transliteration: "Sattvānurūpā sarvasya śraddhā bhavati bhārata |\nŚraddhāmayo'yaṁ puruṣo yo yacchraddhaḥ sa eva saḥ ||",
    hindi: "हे भारत! सब मनुष्यों की श्रद्धा उनके अंतःकरण के अनुरूप होती है। यह मनुष्य श्रद्धामय है; जो जैसी श्रद्धा वाला है, वह स्वयं भी वही है।",
