    sanskrit: "मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु ।\nमामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे ॥",
    transliteration: "Manmanā bhava madbhakto madyājī māṁ namaskuru |\nMāmevaiṣyasi satyaṁ te pratijāne priyo'si me ||",
